#include <cstdio>
#include <algorithm>
#include <vector>
#include <set>
#include <cstring>

using namespace std;

#define INF (1 << 30)

inline int readInt() {
    int x = 0, c;
    while ((c = getchar()) < '0' || c > '9');
    do {
        x = (x << 1) + (x << 3) + (c - '0');
    } while ((c = getchar()) >= '0' && c <= '9');
    return x;
}

int main() {
    int N = readInt(), Q = readInt();

    int stmp[1000000], comp[1000000], a;
    char buff[16];

    for(int i = 0; i < N; i++) {
        stmp[i] = readInt();
        comp[i] = stmp[i];
    }

    sort(comp, comp + N);
    multiset<int> sym;

    while(Q--) {
        scanf("%s", buff);
        a = readInt();
        if(*buff == 'A') {
            sym.insert(stmp[a - 1]);
        } else if(*buff == 'R') {
            auto it = sym.lower_bound(stmp[a - 1]);
            if(it != sym.end()) {
                sym.erase(it);
            }
        } else {
            int left = 0, right = INF;
            while(left != right) {
                int center = (left + right) / 2;
                int pre = 0, BAN = 0;
                for(auto it = sym.begin(); it != sym.end(); it++) {
                    int p = distance(comp, lower_bound(comp, comp + N, *it - center));
                    BAN += max(p - pre, 0);
                    pre = distance(comp, upper_bound(comp, comp + N, *it));
                }
                BAN += max(N - pre, 0);
                if(BAN <= a) right = center;
                else left = center + 1;
            }
            if(left != INF) printf("%d\n", left);
            else puts("NA");
        }
    }
    return 0;
}

